import docs from "../public/index.json";
import { createSearcher, type SearchResult } from "./search.ts";
import { escapeHtml, highlight, normalizeQuery } from "./text.ts";

const API_LIMIT = 10;
const PAGE_LIMIT = 50;
const CACHE_CONTROL = "public, max-age=300";

// _headers rules are not applied to responses generated by a Worker, so mirror the site-wide
// security headers here.
const SECURITY_HEADERS: Record<string, string> = {
    "strict-transport-security": "max-age=31536000; includeSubDomains",
    "content-security-policy":
        "default-src 'self'; object-src 'none'; style-src 'self' 'unsafe-inline'; script-src 'self'",
    "x-frame-options": "SAMEORIGIN",
    "x-content-type-options": "nosniff",
};

const dateFormat = new Intl.DateTimeFormat("en-US", { dateStyle: "long", timeZone: "UTC" });

const searcher = createSearcher(docs);

function withSecurityHeaders(headers: Headers): Headers {
    for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
        headers.set(name, value);
    }
    return headers;
}

function apiSearch(url: URL): Response {
    const query = normalizeQuery(url.searchParams.get("q"));
    const results = searcher
        .search(query, API_LIMIT)
        .map(({ href, title, date, snippet }) => ({ href, title, date, snippet }));

    const headers = withSecurityHeaders(new Headers({ "cache-control": CACHE_CONTROL }));
    headers.set("content-security-policy", "default-src 'none'");
    return Response.json({ query, results }, { headers });
}

function formatDate(date: string): string {
    return dateFormat.format(new Date(date));
}

function renderResult(result: SearchResult): string {
    return `<li class="search-result">
<p class="heading"><a href="${escapeHtml(result.href)}">${escapeHtml(result.title)}</a></p>
<p class="subheading"><time datetime="${escapeHtml(result.date)}">${escapeHtml(formatDate(result.date))}</time></p>
<p class="search-snippet">${highlight(result.snippet, result.terms)}</p>
</li>`;
}

function summarize(query: string, count: number): string {
    if (query === "") {
        return "";
    }
    if (count === 0) {
        return `No results for “${query}”.`;
    }
    const noun = count === 1 ? "result" : "results";
    const capped = count >= PAGE_LIMIT ? "Top " : "";
    return `${capped}${count} ${noun} for “${query}”.`;
}

async function searchPage(url: URL, env: Env): Promise<Response> {
    const query = normalizeQuery(url.searchParams.get("q"));

    // Fetch the page with a fresh request so the visitor's conditional headers (If-None-Match) can't
    // turn this into a 304 for a page whose content now depends on the query.
    const page = await env.ASSETS.fetch(new URL("/search/", url));
    if (!page.ok) {
        return page;
    }

    const results = searcher.search(query, PAGE_LIMIT);
    const resultsHtml = results.map(renderResult).join("\n");
    const summary = summarize(query, results.length);
    const inputHtml =
        `<input type="search" id="search-page-input" name="q" aria-label="Search"` +
        ` placeholder="Search…" value="${escapeHtml(query)}" autocomplete="off" required>`;

    const headers = withSecurityHeaders(new Headers(page.headers));
    for (const name of ["content-length", "etag", "last-modified"]) {
        headers.delete(name);
    }
    headers.set("cache-control", CACHE_CONTROL);
    headers.set("x-robots-tag", "noindex");

    return new HTMLRewriter()
        .on("#search-page-input", {
            element(el) {
                // Replace rather than setAttribute so we control the escaping of the value.
                el.replace(inputHtml, { html: true });
            },
        })
        .on("#search-summary", {
            element(el) {
                el.setInnerContent(summary);
            },
        })
        .on("#search-results", {
            element(el) {
                el.setInnerContent(resultsHtml, { html: true });
            },
        })
        .transform(new Response(page.body, { status: page.status, headers }));
}

export default {
    async fetch(request, env): Promise<Response> {
        const url = new URL(request.url);

        if (request.method !== "GET" && request.method !== "HEAD") {
            return new Response("Method Not Allowed", {
                status: 405,
                headers: withSecurityHeaders(new Headers({ allow: "GET, HEAD" })),
            });
        }

        switch (url.pathname) {
            case "/api/search":
                return apiSearch(url);
            case "/search":
                return Response.redirect(new URL(`/search/${url.search}`, url).toString(), 301);
            case "/search/":
                return await searchPage(url, env);
            default:
                return await env.ASSETS.fetch(request);
        }
    },
} satisfies ExportedHandler<Env>;
